initJs:
function(container, apiUrl, tables) {
  // テスト履歴データの再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.テスト日時 || ""}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間 || ""}</td>
        <td>${r.対象店舗数 || ""}</td>
        <td>${r.MAPE || ""}</td>
        <td>${r.RMSE || ""}</td>
        <td>${r.実行時間 || ""}</td>
        <td>
          <button class="action-btn secondary view-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗一覧の初期化
  function initStoreList() {
    const storeList = container.querySelector("#store-list");
    const storeTable = tables.find(t => t.tableName === "店舗マスタ");
    if (storeTable && storeTable.records) {
      storeList.innerHTML = storeTable.records.map(store => `
        <label><input type="checkbox" name="store" value="${store.id}"> ${store.店舗名 || store.店舗コード}</label>
      `).join("");
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // バリデーション
  function validateTestSettings() {
    const modelSelect = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const selectedStores = container.querySelectorAll('input[name="store"]:checked');
    const selectedCategories = container.querySelectorAll('input[name="category"]:checked');
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');

    if (!modelSelect) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (modelSelect === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (selectedStores.length === 0) {
      showError("店舗が選択されていません。店舗を選択してください。");
      return false;
    }

    if (selectedCategories.length === 0) {
      showError("商品カテゴリが未選択です。商品カテゴリを選択してください。");
      return false;
    }

    if (!selectedDataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    return true;
  }

  // テスト実行
  function executeTest() {
    if (!validateTestSettings()) return;

    // テスト実行中の表示
    const executeBtn = container.querySelector("#btn-test-execute");
    executeBtn.textContent = "テスト実行中...";
    executeBtn.disabled = true;

    // 模擬的なテスト実行（実際のAI処理をシミュレート）
    setTimeout(() => {
      // 精度指標の更新
      container.querySelector("#mape-value").textContent = "12.5";
      container.querySelector("#rmse-value").textContent = "8.3";
      container.querySelector("#mae-value").textContent = "6.7";
      container.querySelector("#r2-value").textContent = "0.85";
      container.querySelector("#execution-time").textContent = "2分15秒";

      // モデルパラメータの表示
      const parametersDiv = container.querySelector("#model-parameters");
      parametersDiv.textContent = `学習率: 0.001
バッチサイズ: 32
エポック数: 100
隠れ層数: 3
ドロップアウト率: 0.2
最適化手法: Adam
損失関数: MSE`;

      // グラフの描画
      drawComparisonChart();

      // テスト履歴に追加
      const newTest = {
        id: Date.now().toString(),
        テスト日時: new Date().toLocaleString(),
        モデル名: container.querySelector("#model-select").value,
        テスト期間: `${container.querySelector("#start-date").value} - ${container.querySelector("#end-date").value}`,
        対象店舗数: container.querySelectorAll('input[name="store"]:checked').length,
        MAPE: "12.5%",
        RMSE: "8.3",
        実行時間: "2分15秒"
      };

      window.aivicApi.save(0, newTest).then(() => {
        window.aivicApi.list(0).then(renderTestHistory);
      });

      executeBtn.textContent = "テスト実行";
      executeBtn.disabled = false;
    }, 3000);
  }

  // グラフ描画
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスサイズ設定
    canvas.width = 800;
    canvas.height = 400;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = "#1a2332";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // グリッド線
    ctx.strokeStyle = "#374151";
    ctx.lineWidth = 1;

    // 縦線
    for (let i = 0; i <= 10; i++) {
      const x = (canvas.width / 10) * i;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, canvas.height);
      ctx.stroke();
    }

    // 横線
    for (let i = 0; i <= 8; i++) {
      const y = (canvas.height / 8) * i;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(canvas.width, y);
      ctx.stroke();
    }

    // サンプルデータ
    const actualData = [120, 135, 110, 145, 160, 155, 140, 165, 150, 175];
    const predictedData = [115, 140, 105, 150, 155, 160, 135, 170, 145, 180];

    // 実績値の線
    ctx.strokeStyle = "#60a5fa";
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = (canvas.width / (actualData.length - 1)) * i;
      const y = canvas.height - (actualData[i] / 200) * canvas.height;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値の線
    ctx.strokeStyle = "#f87171";
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = (canvas.width / (predictedData.length - 1)) * i;
      const y = canvas.height - (predictedData[i] / 200) * canvas.height;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = "#9fb0d1";
    ctx.font = "14px sans-serif";
    ctx.fillText("実績値", 20, 30);
    ctx.fillText("予測値", 20, 50);

    ctx.fillStyle = "#60a5fa";
    ctx.fillRect(80, 22, 20, 2);
    ctx.fillStyle = "#f87171";
    ctx.fillRect(80, 42, 20, 2);
  }

  // CSVエクスポート
  function exportTestResults() {
    window.aivicApi.list(0).then(rows => {
      if (!rows || rows.length === 0) {
        showError("エクスポートするデータがありません");
        return;
      }

      const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(row => [
          row.テスト日時 || "",
          row.モデル名 || "",
          row.テスト期間 || "",
          row.対象店舗数 || "",
          row.MAPE || "",
          row.RMSE || "",
          row.実行時間 || ""
        ].map(field => `"${field}"`).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `model_test_results_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(renderTestHistory);

  // 店舗一覧初期化
  initStoreList();

  // 全店舗選択チェックボックス
  container.querySelector("#select-all-stores").addEventListener("change", (e) => {
    const storeCheckboxes = container.querySelectorAll('input[name="store"]');
    storeCheckboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 全カテゴリ選択チェックボックス
  container.querySelector("#select-all-categories").addEventListener("change", (e) => {
    const categoryCheckboxes = container.querySelectorAll('input[name="category"]');
    categoryCheckboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", executeTest);

  // エクスポートボタン
  container.querySelector("#btn-export-results").addEventListener("click", exportTestResults);

  // 行レベル操作（削除・詳細表示）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      window.aivicApi.list(0).then(renderTestHistory);
      return;
    }

    const viewBtn = e.target.closest(".view-btn");
    if (viewBtn) {
      // 詳細表示（実装例）
      alert("テスト詳細画面を表示します（ID: " + viewBtn.dataset.id + "）");
      return;
    }
  });
}
